/**
 * The QR encoder (src/lib/qr.ts, #1250 part 1) against known answers.
 *
 * Where each expected value comes from:
 *
 * - The Reed-Solomon codewords and the format-information string are the
 *   worked examples ISO/IEC 18004:2015 gives in Annex I.3 (version 1-M,
 *   "01234567") and Annex C (level M, mask 101). They are numeric-mode or
 *   bit-level examples, so they are checked on the exported pieces rather than
 *   through `encodeQr`. node-qrcode 1.5.4's encoder produces the same values.
 * - Whole symbols with the encoder's own mask choice were generated by the
 *   ZXing QR encoder (@zxing/library 0.21.3, `QRCodeEncoder.encode(text,
 *   ErrorCorrectionLevel.M)`), which reads the four penalty rules the same way
 *   src/lib/qr.ts does. Each short text was picked because one rule, or the
 *   order of drawing format bits and scoring, decides its mask: drop that rule
 *   and the symbol changes.
 * - The eight forced-mask symbols of the store link are SHA-256 digests of
 *   node-qrcode 1.5.4's output (`QRCode.create([{ data, mode: "byte" }],
 *   { errorCorrectionLevel: "M", maskPattern })`), rows of "#" (dark) and "."
 *   joined by "\n". A second, independent encoder pins every mask pattern and
 *   both format-information copies.
 *
 * None of the three reference encoders is a dependency of this repo; they
 * were run outside it to produce these literals.
 */
import { createHash } from "node:crypto";
import { describe, expect, it } from "vitest";
import { encodeQr, penaltyScore, reedSolomonRemainder } from "../src/lib/qr";

const STORE_LINK =
  "https://play.google.com/store/apps/details?id=org.unfoldingword.tcmobile";

function picture(modules: readonly (readonly boolean[])[]): string[] {
  return modules.map((row) => row.map((dark) => (dark ? "#" : ".")).join(""));
}

const bits = (s: string): number[] => s.split(" ").map((b) => parseInt(b, 2));

describe("Reed-Solomon (ISO/IEC 18004:2015 Annex I.3)", () => {
  it("gives the ten EC codewords of the 1-M example", () => {
    const data = bits(
      "00010000 00100000 00001100 01010110 01100001 10000000 11101100 00010001 " +
        "11101100 00010001 11101100 00010001 11101100 00010001 11101100 00010001"
    );
    expect(reedSolomonRemainder(data, 10)).toEqual(
      bits(
        "10100101 00100100 11010100 11000001 11101101 00110110 11000111 10000111 00101100 01010101"
      )
    );
  });
});

describe("format information (ISO/IEC 18004:2015 Annex C)", () => {
  it("writes 100000011001110 for level M, mask 101, in both copies", () => {
    const { modules, size } = encodeQr("a", { mask: 5 });
    const at = (row: number, col: number): string =>
      modules[row]?.[col] ? "1" : "0";
    // Bit 14 (most significant) first. Copy 1 runs along row 8 from column 0,
    // skipping the timing column, then up column 8, skipping the timing row.
    const copy1 =
      [0, 1, 2, 3, 4, 5, 7].map((c) => at(8, c)).join("") +
      [8, 7, 5, 4, 3, 2, 1, 0].map((r) => at(r, 8)).join("");
    // Copy 2 runs up column 8 from the bottom, then along row 8 to the right edge.
    const copy2 =
      [0, 1, 2, 3, 4, 5, 6].map((k) => at(size - 1 - k, 8)).join("") +
      [8, 7, 6, 5, 4, 3, 2, 1].map((k) => at(8, size - k)).join("");
    expect(copy1).toBe("100000011001110");
    expect(copy2).toBe("100000011001110");
    expect(at(size - 8, 8)).toBe("1"); // the dark module
  });
});

describe("version selection (Table 7, byte mode, level M)", () => {
  it.each([
    [14, 1],
    [15, 2],
    [26, 2],
    [27, 3],
    [42, 3],
    [62, 4],
    [84, 5],
    [106, 6],
  ])("%i bytes take version %i", (length, version) => {
    const { version: v, size } = encodeQr("x".repeat(length));
    expect(v).toBe(version);
    expect(size).toBe(version * 4 + 17);
  });

  it("counts UTF-8 bytes, not characters", () => {
    expect(encodeQr("é".repeat(7)).version).toBe(1); // 14 bytes
    expect(encodeQr("é".repeat(8)).version).toBe(2); // 16 bytes
  });

  it("throws past version 6-M rather than drawing a symbol", () => {
    expect(() => encodeQr("x".repeat(107))).toThrow(RangeError);
    // 106 bytes is the last that fits (12 + 848 bits of 864); 107 needs 868.
    expect(encodeQr("x".repeat(106)).version).toBe(6);
  });

  it("refuses a mask outside 0 to 7", () => {
    expect(() => encodeQr("a", { mask: 8 })).toThrow(RangeError);
    expect(() => encodeQr("a", { mask: 1.5 })).toThrow(RangeError);
  });
});

/**
 * Reads the data codewords back out of a symbol drawn with mask 0, so a test
 * can lock what `encodeQr` wrote and not only which version it picked. Only
 * versions 1 and 6 are modelled: neither has version-information blocks, and
 * version 1 has no alignment pattern. The function-module test and the zigzag
 * order below are written from ISO/IEC 18004:2015 7.7.3 and Figure 3, not
 * copied from src/lib/qr.ts.
 */
function readDataCodewords(text: string, version: 1 | 6): number[] {
  const { modules, size } = encodeQr(text, { mask: 0 });
  const isFunction = (r: number, c: number): boolean =>
    (r < 9 && c < 9) ||
    (r < 9 && c >= size - 8) ||
    (r >= size - 8 && c < 9) ||
    r === 6 ||
    c === 6 ||
    (version === 6 &&
      Math.abs(r - (size - 7)) <= 2 &&
      Math.abs(c - (size - 7)) <= 2);
  const out: number[] = [];
  let bit = 0;
  let cur = 0;
  let upward = true;
  for (let right = size - 1; right >= 1; right -= 2) {
    if (right === 6) right = 5;
    for (let step = 0; step < size; step++) {
      const r = upward ? size - 1 - step : step;
      for (const c of [right, right - 1]) {
        if (isFunction(r, c)) continue;
        const dark = (modules[r]?.[c] ?? false) !== ((r + c) % 2 === 0);
        cur = (cur << 1) | (dark ? 1 : 0);
        if (++bit % 8 === 0) {
          out.push(cur);
          cur = 0;
        }
      }
    }
    upward = !upward;
  }
  return out;
}

/** The byte-mode stream: 0100, an 8-bit count, the bytes, then 0000 and padding. */
function byteModeStream(bytes: Uint8Array, capacity: number): number[] {
  const bitString =
    "0100" +
    bytes.length.toString(2).padStart(8, "0") +
    [...bytes].map((b) => b.toString(2).padStart(8, "0")).join("");
  const padded = (bitString + "0000").padEnd(
    Math.ceil((bitString.length + 4) / 8) * 8,
    "0"
  );
  const out: number[] = [];
  for (let i = 0; i < padded.length; i += 8)
    out.push(parseInt(padded.slice(i, i + 8), 2));
  for (let pad = 0xec; out.length < capacity; pad ^= 0xec ^ 0x11) out.push(pad);
  return out.slice(0, capacity);
}

describe("codewords written by encodeQr (byte mode, mask 0)", () => {
  it("locks the UTF-8 bytes and the 8-bit count of a non-ASCII text, version 1", () => {
    const text = "é€"; // C3 A9, E2 82 AC: five bytes for two characters
    const bytes = new TextEncoder().encode(text);
    expect([...bytes]).toEqual([0xc3, 0xa9, 0xe2, 0x82, 0xac]);
    const data = readDataCodewords(text, 1).slice(0, 16);
    // 0100 00000101 | 11000011 10101001 11100010 10000010 10101100 | 0000
    expect(data.slice(0, 8)).toEqual([
      0x40, 0x5c, 0x3a, 0x9e, 0x28, 0x2a, 0xc0, 0xec,
    ]);
    expect(data).toEqual(byteModeStream(bytes, 16));
  });

  it("locks the 106-byte text that exactly fills version 6-M, four blocks interleaved", () => {
    const text = "é".repeat(53); // 106 bytes
    const bytes = new TextEncoder().encode(text);
    expect(bytes.length).toBe(106);
    const interleaved = readDataCodewords(text, 6).slice(0, 108);
    const stream = byteModeStream(bytes, 108);
    const blocks = [0, 1, 2, 3].map((k) => stream.slice(k * 27, (k + 1) * 27));
    expect(interleaved).toEqual(
      Array.from({ length: 108 }, (_, i) => blocks[i % 4]?.[Math.floor(i / 4)])
    );
  });
});

describe("penalty score (7.8.3.1, Table 11), on hand-built matrices", () => {
  const square = (
    n: number,
    dark: (r: number, c: number) => boolean
  ): boolean[][] =>
    Array.from({ length: n }, (_, r) =>
      Array.from({ length: n }, (_, c) => dark(r, c))
    );

  it("scores a 10x10 checkerboard 0: no runs, no blocks, no finder-like runs, half dark", () => {
    expect(penaltyScore(square(10, (r, c) => (r + c) % 2 === 0))).toBe(0);
  });

  it("scores an all-light 10x10 as rules 1, 2 and 4 by hand", () => {
    // Rule 1: 20 lines, each one run of 10: 20 x (3 + 5) = 160.
    // Rule 2: 9 x 9 = 81 blocks of 2x2: 81 x 3 = 243.
    // Rule 4: 0% dark is ten 5% steps from 50%: 10 x 10 = 100.
    expect(penaltyScore(square(10, () => false))).toBe(160 + 243 + 100);
  });

  // A 10x10 checkerboard (score 0, 50 dark) with some of row 9's light cells
  // turned dark. Row 9's even columns are the light ones.
  const checkerWithRow9Dark = (columns: readonly number[]): boolean[][] =>
    square(10, (r, c) => (r + c) % 2 === 0 || (r === 9 && columns.includes(c)));

  it("scores 55% dark as one 5% step: rule 1's run of 10 plus rule 4", () => {
    // Row 9 is all dark: one run of 10, 3 + 5 = 8. No column gets a run of 5,
    // no 2x2 block forms (row 8 still alternates), 55 dark: 10 x 1 = 10.
    expect(penaltyScore(checkerWithRow9Dark([0, 2, 4, 6, 8]))).toBe(8 + 10);
  });

  it("scores 54% dark as no 5% step: rule 1's run of 8 only", () => {
    // Columns 0 to 7 of row 9 are dark: one run of 8, 3 + 3 = 6. 54 dark is
    // less than one whole 5% step from 50%, so rule 4 adds nothing.
    expect(penaltyScore(checkerWithRow9Dark([0, 2, 4, 6]))).toBe(6);
  });

  it("counts a finder-like run at the edge, the area outside counting as light", () => {
    // Row 0 becomes 1011101010: dark-light-dark-dark-dark-light-dark from column
    // 0, with nothing but the quiet zone to its left. To its right only three
    // modules remain, one of them dark. Flipping column 3 of row 0 makes no run
    // of 5, no 2x2 block and 51 dark, so rule 3 is the whole score.
    const cells = square(
      10,
      (r, c) => (r + c) % 2 === 0 || (r === 0 && c === 3)
    );
    expect(picture(cells)[0]).toBe("#.###.#.#.");
    expect(penaltyScore(cells)).toBe(40);
  });
});

