describe("whole symbols, mask chosen by the penalty rules", () => {
  it.each(ZXING.map((v) => [v.text, v] as const))(
    "%j matches ZXing",
    (_, v) => {
      const qr = encodeQr(v.text);
      expect([qr.version, qr.mask]).toEqual([v.version, v.mask]);
      expect(picture(qr.modules)).toEqual(v.rows);
    }
  );
});

/** node-qrcode 1.5.4, the store link at each forced mask (see the header). */
const STORE_LINK_BY_MASK = [
  "b4256152f4526c50a529274c3f4d81cb0ee3ae5c46b62a0fbb67abfc296ef4e1",
  "79997c0867505b5a33189303a724a56932b971743fd1768f3771500aa340b337",
  "fd89a2df3e41655ea5e9d7a435c1a7b1e8a41d3538c9956236dd1598c5dfd90c",
  "ba2fd073c7c0e2c95337e1656aa0309b51b6fe08d87c29435a1cadebc3564efd",
  "d40f16d91491a4f4c5f62822e4b2c59666c4cc666c6e0aee611e0e63c4613f09",
  "f3f5d2859431203ff4b8a0f79c06dcc7ffbd9d5abb4ef98b4c66222180feb2d2",
  "2958fdf7d64f04b50955bc3fbfab82db2f0976bfc2e94994a114d697fe04d6ab",
  "4600365bf3ea0ade90db2a261fffa3b8d5c32dbf7fd4cd8b70c515e86d64ad30",
];

describe("every mask pattern and its format bits", () => {
  it.each(STORE_LINK_BY_MASK.map((digest, mask) => [mask, digest] as const))(
    "the store link at mask %i matches node-qrcode",
    (mask, digest) => {
      const qr = encodeQr(STORE_LINK, { mask });
      expect(qr.mask).toBe(mask);
      expect(
        createHash("sha256")
          .update(picture(qr.modules).join("\n"))
          .digest("hex")
      ).toBe(digest);
    }
  );
});
